-- лише якщо немає продукту з тим самим нормалізованим URL АБО назвою, інакше наявному лише додаються категорія й
-- підкатегорія. Id тарифів — за product_id + plan_name. Повторний запуск безпечний.
-- Автор — whitevelvetelf@gmail.com (id за email). Статус published, партнерство «Знайдено».
-- =====================================================================

INSERT IGNORE INTO `subcategories` (`category_id`, `name`, `name_en`, `slug`) SELECT c.`id`, 'HR і рекрутинг', 'HR & Recruiting', 'hr-recruiting' FROM `categories` c WHERE c.`slug` = 'business-marketing' LIMIT 1;

SET @uid = (SELECT `id` FROM `users` WHERE `email` = 'whitevelvetelf@gmail.com' LIMIT 1);

-- Kickresume — HR і рекрутинг
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'kickresume.com' OR LOWER(`name`) = LOWER('Kickresume'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Kickresume', NULL, 'https://www.kickresume.com', NULL, NULL, 'AI-конструктор резюме, супровідних листів і персональних сайтів: 40+ шаблонів, AI-автор тексту, перевірка резюме на сумісність з ATS і карта кар''єри.', 'An AI builder for resumes, cover letters and personal websites: 40+ templates, an AI writer, an ATS resume checker and a career map.', 'Kickresume допомагає швидко скласти резюме та супровідний лист, які виглядають професійно й проходять автоматичні системи відбору (ATS). AI пише й покращує тексти розділів, перевірка ATS показує, що виправити, а Career Map підказує можливі кар''єрні кроки. Доступно понад 40 шаблонів резюме й листів, тисячі прикладів і готових формулювань, а також конструктор персонального сайту. Дані зберігаються в ЄС відповідно до GDPR. Тарифи: Free — базові шаблони; Premium — $24 на місяць, $18 на місяць при оплаті за квартал ($54) або $8 на місяць при річній оплаті ($96); діє 14-денна гарантія повернення коштів.', 'Kickresume helps you quickly put together a resume and cover letter that look professional and pass applicant tracking systems (ATS). AI writes and improves section text, the ATS checker shows what to fix and Career Map suggests possible career moves. There are 40+ resume and cover letter templates, thousands of examples and ready phrases, and a personal website builder. Data is hosted in the EU under GDPR. Plans: Free — basic templates; Premium — $24 a month, $18 a month billed quarterly ($54) or $8 a month billed yearly ($96); a 14-day money-back guarantee applies.', 'AI-автор резюме й супровідних листів
40+ шаблонів
Перевірка резюме для ATS
Карта кар''єри та персональний сайт', 'AI resume and cover letter writer
40+ templates
ATS resume checker
Career Map and personal website', 'Шукачі роботи, студенти й випускники, які хочуть швидко зробити сильне резюме англійською.', 'Job seekers, students and graduates who want to create a strong resume quickly.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
