-- Rezi — HR і рекрутинг
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'rezi.ai' OR LOWER(`name`) = LOWER('Rezi'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Rezi', NULL, 'https://www.rezi.ai', NULL, NULL, 'AI-конструктор резюме з підбором ключових слів під вакансію, перевіркою на сумісність з ATS і практикою співбесід.', 'An AI resume builder with keyword targeting for each job, ATS compatibility checks and interview practice.', 'Rezi допомагає створювати й адаптувати резюме під конкретні вакансії. AI пише пункти досвіду, підбирає ключові слова з опису вакансії та перевіряє, чи пройде резюме автоматичні системи відбору (ATS); є також AI-практика співбесід. За даними компанії, з 2019 року сервісом скористалися понад 4,5 млн шукачів роботи, а 62% із них отримують запрошення на співбесіду. Тарифи: Free — 1 резюме й обмежені AI-інструменти; Pro — $29 на місяць (необмежені резюме, повний доступ до AI, щомісячна експертна перевірка); Lifetime — $149 одноразово; для організацій — $99 на місяць за 200 користувачів. На всі тарифи діє 30-денна гарантія повернення коштів.', 'Rezi helps you create and tailor resumes for specific jobs. AI writes experience bullet points, picks keywords from the job description and checks whether the resume will pass applicant tracking systems (ATS); there is also AI interview practice. According to the company, more than 4.5 million job seekers have used it since 2019, and 62% of them land an interview. Plans: Free — 1 resume and limited AI tools; Pro — $29 a month (unlimited resumes, full AI access, a monthly expert review); Lifetime — $149 one-time; for organisations — $99 a month per 200 users. All plans have a 30-day money-back guarantee.', 'AI-тексти для пунктів досвіду
Ключові слова з опису вакансії
Перевірка на сумісність з ATS
Практика співбесід', 'AI-written experience bullet points
Keywords from the job description
ATS compatibility check
Interview practice', 'Шукачі роботи, які подаються на багато вакансій і хочуть адаптувати резюме під кожну.', 'Job seekers applying to many roles who want to tailor their resume to each one.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
