-- Workable — HR і рекрутинг
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'workable.com' OR LOWER(`name`) = LOWER('Workable'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Workable', NULL, 'https://www.workable.com', NULL, NULL, 'Платформа для найму та HR з AI-агентом рекрутера: пошук кандидатів серед 400+ млн профілів, ATS, розміщення вакансій на 200+ сайтах і HR-система.', 'A hiring and HR platform with an AI recruiting agent: sourcing from 400M+ profiles, an ATS, posting to 200+ job boards and an HR system.', 'Workable об''єднує рекрутинг і HR в одній системі. Вакансії публікуються одразу на понад 200 сайтах, кандидатів можна шукати серед понад 400 млн профілів, а система відстеження кандидатів (ATS) допомагає вести відбір і планувати співбесіди. HR-частина охоплює онбординг, відпустки, підготовку до виплати зарплат, довідник працівників і оргструктуру. AI-агент Workable бере на себе частину роботи рекрутера й оплачується кредитами: кожен платний акаунт отримує 3 000 безкоштовних кредитів, далі $0,095–0,12 за кредит. Тарифи на місяць: Standard — $299 (до 20 працівників); Premier — $599; Enterprise — $719; при річній оплаті на 20% дешевше. Є 15-денний пробний період.', 'Workable combines recruiting and HR in one system. Jobs are posted to 200+ job boards at once, candidates can be sourced from 400M+ profiles, and the applicant tracking system (ATS) helps run the selection process and schedule interviews. The HR side covers onboarding, time off, payroll preparation, an employee directory and org charts. The Workable AI agent takes over part of the recruiter''s work and is paid for with credits: every paid account gets 3,000 free credits, then $0.095–0.12 per credit. Monthly plans: Standard — $299 (up to 20 employees); Premier — $599; Enterprise — $719; 20% cheaper billed annually. There is a 15-day free trial.', 'Публікація вакансій на 200+ сайтах
Пошук серед 400+ млн профілів
ATS і планування співбесід
HR-система: онбординг, відпустки
AI-агент рекрутера', 'Posting to 200+ job boards
Sourcing from 400M+ profiles
ATS and interview scheduling
HR system: onboarding, time off
AI recruiting agent', 'Малий і середній бізнес та HR-команди, які регулярно наймають людей.', 'Small and mid-sized businesses and HR teams that hire regularly.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
