SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'metaview.ai' OR LOWER(`name`) = LOWER('Metaview'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Metaview', NULL, 'https://www.metaview.ai', NULL, NULL, 'AI-платформа для рекрутингу: автоматично веде нотатки співбесід, шукає кандидатів і переглядає заявки, а ще дає аналітику найму.', 'An AI recruiting platform: it takes interview notes automatically, sources candidates and reviews applications, and provides hiring analytics.', 'Metaview знімає з рекрутерів рутину. Під час співбесід AI веде нотатки й готує зведення для відгуку через 10–20 хвилин після розмови, агенти самостійно шукають кандидатів і переглядають заявки за налаштованими правилами, а профіль ідеального кандидата уточнюється на основі рішень команди. Платформа інтегрується з Ashby, Greenhouse, Lever та іншими ATS і дає аналітику процесу найму. Тарифи за користувача на місяць: Free — перші 100 профілів пошуку; Pro — $100 (200 профілів на місяць); Max — $300 (необмежений пошук); Enterprise — за запитом.', 'Metaview takes routine work off recruiters'' plates. During interviews AI takes notes and prepares a summary for feedback within 10–20 minutes of the conversation, agents source candidates and review applications on their own according to set rules, and the Ideal Candidate Profile is refined based on the team''s decisions. It integrates with Ashby, Greenhouse, Lever and other ATS and provides hiring analytics. Plans per user a month: Free — the first 100 sourced profiles; Pro — $100 (200 profiles a month); Max — $300 (unlimited sourcing); Enterprise on request.', 'Автоматичні нотатки співбесід
AI-пошук кандидатів і перегляд заявок
Профіль ідеального кандидата
Інтеграція з Ashby, Greenhouse, Lever', 'Automatic interview notes
AI candidate sourcing and application review
Ideal Candidate Profile
Ashby, Greenhouse and Lever integration', 'Рекрутери й команди найму в компаніях, які проводять багато співбесід.', 'Recruiters and hiring teams at companies that run many interviews.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
